def subtract(a, b):
    # Filter out empty intervals and sort by start position
    a_filtered = sorted([interval for interval in a if interval[0] < interval[1]])
    b_filtered = sorted([interval for interval in b if interval[0] < interval[1]])

    # Merge overlapping intervals in b
    b_merged = []
    for start, end in b_filtered:
        if b_merged and start <= b_merged[-1][1]:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Perform subtraction
    result = []
    for a_start, a_end in a_filtered:
        current_start = a_start
        for b_start, b_end in b_merged:
            if b_end <= current_start or b_start >= a_end:
                # No overlap
                continue
            if current_start < b_start:
                # Add the part before b_start
                result.append([current_start, b_start])
            current_start = max(current_start, b_end)

        if current_start < a_end:
            result.append([current_start, a_end])

    # Merge touching intervals
    merged = []
    for start, end in result:
        if merged and merged[-1][1] == start:
            merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged

